function sw(){if(document.getElementById('kpsLang'))return;var h=document.querySelector('header');if(!h)return;var d=document.createElement('div');d.id='kpsLang';d.setAttribute('data-noi18n','');d.setAttribute('role','group');d.setAttribute('aria-label','Til / Language / Язык');
  d.style.cssText='display:inline-flex;border:1px solid #cfccc5;border-radius:2px;overflow:hidden;margin:0 6px;flex:none;background:#fff';
  ['uz','en','ru'].forEach(function(k){var b=document.createElement('button');b.type='button';b.textContent=k.toUpperCase();b.style.cssText='border:0;padding:0 8px;height:26px;font:500 10.5px/26px "IBM Plex Mono",monospace;letter-spacing:.08em;cursor:pointer;'+(k===L?'background:#141414;color:#f4f3f1':'background:transparent;color:#141414');
    b.onclick=function(){try{localStorage.setItem('kps_lang',k);}catch(e){}location.reload();};d.appendChild(b);});
  var sp=h.querySelector('.sp, .spacer, [class*="sp"]');var last=h.lastElementChild;if(sp&&sp.nextSibling)h.insertBefore(d,sp.nextSibling);else h.appendChild(d);}
document.documentElement.lang=L;window.kpsT=function(x){return x;};
