var D=DICT[L]||{},NUM=/\d+(?:[.,]\d+)?/g,DN={},FR=[];
Object.keys(D).forEach(function(k){if(/\d/.test(k))DN[k.replace(NUM,'#')]=k;if(k.length>=7&&/\s/.test(k))FR.push(k);});FR.sort(function(a,b){return b.length-a.length;});
var LET=/[A-Za-zʻʼ'Ѐ-ӿ]/;
function frag(t){var r=t,cov=0;for(var i=0;i<FR.length;i++){var f=FR[i],p=r.indexOf(f);if(p<0)continue;var out='',s=0;while(p>=0){var a=r.charAt(p-1),b=r.charAt(p+f.length);if((p===0||!LET.test(a))&&(p+f.length===r.length||!LET.test(b))){out+=r.slice(s,p)+'\u0001'+i+'\u0002';s=p+f.length;cov+=f.length;}p=r.indexOf(f,p+1);}r=out+r.slice(s);}
  if(!cov||cov<t.replace(/[^A-Za-zʻʼ'\u0400-\u04FF]/g,'').length*0.8)return null;return r.replace(/\u0001(\d+)\u0002/g,function(_,i){return D[FR[+i]];});}
function one(t){var v=D[t];if(v!=null)return v;if(/\d/.test(t)){var k=DN[t.replace(NUM,'#')];if(k){var n=t.match(NUM),i=0;return D[k].replace(NUM,function(){return n[i++]||'';});}}return null;}
function seg(t){var parts=t.split(/( — | · |: | \| |, |; | \/ )/);if(parts.length<2)return null;var ok=true,out=parts.map(function(p,i){if(i%2)return p;var q=p.trim();if(!q||!LET.test(q))return p;var v=one(q);if(v==null){ok=false;return p;}return p.replace(q,v);});return ok?out.join(''):null;}
function tr(s){var t=s.trim();if(!t||!LET.test(t))return null;var v=one(t);if(v!=null)return s.replace(t,v);
  var g=seg(t);if(g)return s.replace(t,g);if(t.length>=8){var f=frag(t);if(f)return s.replace(t,f);}return null;}
var SKIP='script,style,textarea,[data-noi18n],#paper,.th,#ed,#kpsLang,.leaflet-tile-pane,code,pre,#aiOut,.ai';
function walk(root){if(!root)return;if(root.nodeType===3){node(root);return;}if(root.nodeType!==1)return;if(root.closest&&root.closest(SKIP))return;
  var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,null),n,list=[];while((n=w.nextNode()))list.push(n);list.forEach(node);
  attrs(root);if(root.querySelectorAll)root.querySelectorAll('[title],[placeholder],[aria-label]').forEach(attrs);}
function node(n){var p=n.parentElement;if(!p||p.closest(SKIP))return;var r=tr(n.nodeValue);if(r!=null&&r!==n.nodeValue)n.nodeValue=r;}
function attrs(el){if(!el.getAttribute||el.closest(SKIP))return;['title','placeholder','aria-label'].forEach(function(a){var v=el.getAttribute(a);if(v){var r=tr(v);if(r!=null&&r!==v)el.setAttribute(a,r);}});}
function run(){sw();walk(document.body);var t=tr(document.title);if(t)document.title=t;
  new MutationObserver(function(ms){ms.forEach(function(m){if(m.type==='characterData')node(m.target);else if(m.type==='attributes')attrs(m.target);else m.addedNodes.forEach(walk);});}).observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['title','placeholder','aria-label']});}
